package uk.wrekinlabs.jarvis;

import android.Manifest;
import android.app.*;
import android.os.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.speech.tts.*;
import android.view.*;
import android.widget.*;
import android.text.*;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Original native Jarvis HUD. User-only local commands; model output is always text. */
public class MainActivity extends Activity {
    private static final int BG=0xff080f1c,PANEL=0xff111f30,EDGE=0xff233a50,TEXT=0xffe8f4fa,MUTED=0xff9db3c6,ACCENT=0xff72eee0;
    private static final int MIC_PERMISSION=100,IMPORT=11,EXPORT=12;
    private LinearLayout page,transcript,memoryList;private EditText input;private TextView reply,status;
    private OrbView orb;private TextToSpeech speech;private VoiceInput voice;private boolean speechReady,foreground,busy;
    private String screen="Jarvis",draft="",lastReply="Ready when you are, Andrew.",lastSpoken="";
    private PairingStore pairing;private ConversationStore conversations;
    private final ArrayList<String> selectedNotes=new ArrayList<>();
    private final java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();
    private BridgeClient request;private int generation;

    @Override public void onCreate(Bundle saved){
        super.onCreate(saved);pairing=new PairingStore(this);conversations=new ConversationStore(this);
        if(saved!=null){draft=saved.getString("draft","");lastReply=saved.getBoolean("busy")?"The previous request was interrupted. You can send it again.":saved.getString("reply",lastReply);ArrayList<String> notes=saved.getStringArrayList("attachments");if(notes!=null)selectedNotes.addAll(notes);}
        voice=new VoiceInput(this,new VoiceInput.Listener(){
            public void state(String value){setState(value);}
            public void partial(String value){if(input!=null)input.setText(value);}
            public void result(String value){setState("READY");if(input!=null){input.setText(value);input.setSelection(input.length());if(prefs().getBoolean("voice_send",false))submit();else answer("I heard you. Review the words, then tap Send.",false);}}
            public void error(String message){setState("ERROR");answer(message,false);}
        });
        speech=new TextToSpeech(this,result->{if(result==TextToSpeech.SUCCESS&&!isDestroyed()){speechReady=speech.setLanguage(Locale.UK)>=0;applyVoice();speech.setOnUtteranceProgressListener(new UtteranceProgressListener(){
            public void onStart(String id){runOnUiThread(()->{if(foreground)setState("SPEAKING");});}
            public void onDone(String id){runOnUiThread(()->{if(foreground&&!busy)setState("READY");});}
            public void onError(String id){runOnUiThread(()->{if(foreground){setState("ERROR");toast("Speech output is unavailable. The reply is still on screen.");}});}
        });}});
        show(saved==null?"Jarvis":saved.getString("screen","Jarvis"));
    }
    private android.content.SharedPreferences prefs(){return getSharedPreferences("jarvis",MODE_PRIVATE);}
    private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
    private GradientDrawable background(int color,int border,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));d.setStroke(dp(1),border);return d;}
    private TextView label(String value,int size,int color){TextView v=new TextView(this);v.setText(value);v.setTextColor(color);v.setTextSize(size);v.setPadding(0,dp(6),0,dp(6));return v;}
    private void text(String value,int size,int color){page.addView(label(value,size,color));}
    private Button makeButton(String title,boolean primary,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextSize(14);b.setTextColor(primary?BG:TEXT);b.setBackground(background(primary?ACCENT:PANEL,primary?ACCENT:EDGE,14));b.setMinHeight(dp(48));b.setPadding(dp(12),dp(6),dp(12),dp(6));b.setOnClickListener(v->action.run());return b;}
    private Button button(String title,Runnable action){Button b=makeButton(title,false,action);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(52));lp.setMargins(0,dp(5),0,dp(5));page.addView(b,lp);return b;}
    private void row(String left,Runnable a,String right,Runnable b){LinearLayout row=new LinearLayout(this);row.setPadding(0,dp(5),0,dp(5));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(48),1);lp.setMargins(0,0,dp(5),0);row.addView(makeButton(left,false,a),lp);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(0,dp(48),1);rp.setMargins(dp(5),0,0,0);row.addView(makeButton(right,false,b),rp);page.addView(row);}
    private EditText edit(String hint,boolean password){EditText e=new EditText(this);e.setTextColor(TEXT);e.setHintTextColor(MUTED);e.setTextSize(16);e.setHint(hint);e.setPadding(dp(14),dp(12),dp(14),dp(12));e.setBackground(background(BG,EDGE,12));if(password){e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);e.setSaveEnabled(false);e.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(7),0,dp(7));page.addView(e,lp);return e;}
    private void heading(String title,String subtitle){text(title,27,TEXT);text(subtitle,14,MUTED);}
    private void show(String tab){
        if(input!=null)draft=input.getText().toString();cancelRequest();if(voice!=null)voice.close();if(speech!=null)speech.stop();screen=tab;input=null;reply=null;orb=null;status=null;transcript=null;
        LinearLayout shell=new LinearLayout(this);shell.setOrientation(LinearLayout.VERTICAL);shell.setBackgroundColor(BG);setContentView(shell);
        shell.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});shell.requestApplyInsets();
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(dp(20),dp(15),dp(20),dp(22));scroll.addView(page);shell.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        TextView brand=label("WREKIN LABS     /     PERSONAL ASSISTANT",10,ACCENT);brand.setLetterSpacing(.13f);page.addView(brand);
        switch(tab){case "Memory":memory();break;case "Tasks":tasks();break;case "Settings":settings();break;default:screen="Jarvis";home();}
        LinearLayout nav=new LinearLayout(this);nav.setPadding(dp(6),dp(8),dp(6),dp(8));nav.setBackgroundColor(PANEL);
        for(String name:new String[]{"Jarvis","Memory","Tasks","Settings"}){Button b=makeButton(name,name.equals(screen),()->show(name));b.setTextSize(12);b.setId(name.equals("Memory")?R.id.nav_memory:name.equals("Settings")?R.id.nav_settings:name.equals("Jarvis")?R.id.nav_home:R.id.nav_tasks);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(48),1);lp.setMargins(dp(3),0,dp(3),0);nav.addView(b,lp);}shell.addView(nav);
    }
    private void home(){
        TextView title=label("J A R V I S",34,TEXT);title.setGravity(Gravity.CENTER);title.setTypeface(Typeface.create("sans-serif-light",Typeface.NORMAL));page.addView(title);
        status=label(pairing.configured()?"AI BRIDGE CONFIGURED  •  NOT YET VERIFIED":"LOCAL MODE  •  READY",11,ACCENT);status.setGravity(Gravity.CENTER);status.setId(R.id.connection_status);page.addView(status);
        orb=new OrbView(this);orb.setMotion(!prefs().getBoolean("reduce_motion",false));orb.setOnClickListener(v->listen());page.addView(orb,new LinearLayout.LayoutParams(-1,dp(205)));
        TextView greeting=label("At your service, Andrew.",21,TEXT);greeting.setGravity(Gravity.CENTER);page.addView(greeting);
        text("Ask a question, remember an idea, or give me a phone command.",14,MUTED);
        row("What can you do?",()->runText("What can you do?"),"Battery status",()->runText("Battery"));
        input=edit("Type here, or tap the core to speak…",false);input.setId(R.id.message_input);input.setMinLines(2);input.setGravity(Gravity.TOP);input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(4000)});input.setText(draft);
        LinearLayout actions=new LinearLayout(this);Button mic=makeButton("Speak",false,()->listen());mic.setContentDescription("Start voice input");actions.addView(mic,new LinearLayout.LayoutParams(0,dp(52),1));Button send=makeButton("Send",true,()->submit());send.setId(R.id.send_message);LinearLayout.LayoutParams sendLp=new LinearLayout.LayoutParams(0,dp(52),2);sendLp.setMargins(dp(8),0,0,0);actions.addView(send,sendLp);page.addView(actions);
        row("Save note",()->saveDraft(),"Attach notes ("+selectedNotes.size()+")",()->chooseNotes());
        text("AI sends the recent conversation and notes you select. Local commands stay on your phone.",11,MUTED);
        reply=label(lastReply,16,TEXT);reply.setId(R.id.reply_text);reply.setTextIsSelectable(true);reply.setPadding(dp(16),dp(16),dp(16),dp(16));reply.setBackground(background(PANEL,EDGE,16));LinearLayout.LayoutParams replyLp=new LinearLayout.LayoutParams(-1,-2);replyLp.setMargins(0,dp(14),0,dp(8));page.addView(reply,replyLp);
        row("Read reply",()->speak(lastSpoken.isEmpty()?lastReply:lastSpoken),"Stop",()->stopAll());
        text("CONVERSATION",11,ACCENT);transcript=new LinearLayout(this);transcript.setOrientation(LinearLayout.VERTICAL);page.addView(transcript);renderConversation();
        button("New conversation",()->new AlertDialog.Builder(this).setTitle("Clear this conversation?").setMessage("Saved notes are kept. Future questions will start without this chat history.").setNegativeButton("Keep",null).setPositiveButton("Clear",(d,w)->{if(conversations.clear()){selectedNotes.clear();lastReply="A fresh start. What shall we work on?";show("Jarvis");}else toast("Could not clear conversation.");}).show());
    }
    private void renderConversation(){if(transcript==null)return;transcript.removeAllViews();JSONArray turns=conversations.turns();if(turns.length()==0){transcript.addView(label("Your conversation will appear here.",14,MUTED));return;}for(int i=turns.length()-1;i>=0;i--){JSONObject t=turns.optJSONObject(i);if(t==null)continue;LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(14),dp(10),dp(14),dp(10));card.setBackground(background(PANEL,EDGE,14));card.addView(label("YOU  /  "+t.optString("question"),14,MUTED));TextView a=label("JARVIS  /  "+t.optString("answer"),15,TEXT);a.setTextIsSelectable(true);card.addView(a);card.addView(label("ai".equals(t.optString("source"))?"AI conversation":"On-phone response",10,ACCENT));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(5),0,dp(5));transcript.addView(card,lp);}}
    private void runText(String text){if(input!=null)input.setText(text);submit();}
    private void submit(){if(input==null)return;String q=input.getText().toString().trim();if(q.isEmpty()){answer("I'm listening. Type a question or tap Speak.",false);return;}if(busy){answer("I'm still working on the last question. Tap Stop to cancel it first.",false);return;}voice.close();speech.stop();LocalCommand command=LocalCommand.parse(q);if(!command.kind.equals("chat")){local(q,command);return;}startRequest(q);}
    private void local(String q,LocalCommand command){String result;switch(command.kind){
        case "time":result="It's "+java.time.LocalTime.now().format(java.time.format.DateTimeFormatter.ofPattern("HH:mm",Locale.UK))+", Andrew.";break;
        case "date":result=java.time.LocalDate.now().format(java.time.format.DateTimeFormatter.ofPattern("EEEE, d MMMM yyyy",Locale.UK));break;
        case "battery":Intent battery=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));int level=battery==null?-1:battery.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),scale=battery==null?0:battery.getIntExtra(BatteryManager.EXTRA_SCALE,100);result=level<0||scale<=0?"Battery status isn't available.":"Your phone battery is at "+Math.round(level*100f/scale)+"%.";break;
        case "remember":result=saveNote(command.value)?"Noted. I've saved that on your phone.":"I couldn't save the note. Check the Memory page.";break;
        case "notes":show("Memory");return;
        case "wifi":open(new Intent(android.provider.Settings.ACTION_WIFI_SETTINGS),"Opening Wi-Fi settings. Choose any changes there.");return;
        case "bluetooth":open(new Intent(android.provider.Settings.ACTION_BLUETOOTH_SETTINGS),"Opening Bluetooth settings. Choose any changes there.");return;
        case "calculator":open(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_APP_CALCULATOR),"Opening the calculator.");return;
        case "timer":Intent timer=new Intent(android.provider.AlarmClock.ACTION_SET_TIMER).putExtra(android.provider.AlarmClock.EXTRA_LENGTH,Integer.parseInt(command.value)).putExtra(android.provider.AlarmClock.EXTRA_MESSAGE,"Jarvis timer").putExtra(android.provider.AlarmClock.EXTRA_SKIP_UI,false);open(timer,"Opening the Clock app with your timer request. Check its timer screen.");return;
        case "stop":stopAll();return;
        default:result="On this phone I can tell you the time, date and battery level; remember a note; show notes; open Wi-Fi, Bluetooth or the calculator; and request a timer, such as ‘timer 10 minutes’. For general questions, connect your AI bridge in Settings. I cannot control your PC yet.";
    }conversations.add(q,result,"local");input.setText("");draft="";setState("READY");answer(result,true);renderConversation();}
    private void open(Intent intent,String message){try{startActivity(intent);answer(message,false);}catch(ActivityNotFoundException|SecurityException e){answer("This phone has no available app for that command.",false);setState("ERROR");}}
    private void listen(){if(!screen.equals("Jarvis"))return;cancelRequest();if(speech!=null)speech.stop();if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},MIC_PERMISSION);return;}voice.start(prefs().getBoolean("local_speech",false));}
    @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(code==MIC_PERMISSION){if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED&&foreground)listen();else answer("Microphone permission was not granted. Typing still works.",false);}}
    private void setState(String state){if(orb!=null)orb.setState(state);if(status!=null)status.setText(state.equals("READY")?(pairing.configured()?"AI BRIDGE CONFIGURED  •  LOCAL COMMANDS READY":"LOCAL MODE  •  READY"):state);}
    private void answer(String text,boolean read){lastReply=text;lastSpoken=text;if(reply!=null)reply.setText(text);if(read&&prefs().getBoolean("speak_replies",true))speak(text);}
    private void speak(String text){if(!foreground)return;if(!speechReady){toast("Speech is not ready. Your reply is on screen.");return;}voice.close();applyVoice();String spoken=text.length()>3500?text.substring(0,3500)+". The rest is on screen.":text;speech.speak(spoken,TextToSpeech.QUEUE_FLUSH,null,"jarvis-"+System.nanoTime());}
    private void applyVoice(){if(speech==null)return;speech.setSpeechRate(prefs().getFloat("speech_rate",.95f));String name=prefs().getString("voice","");Set<Voice> voices=speech.getVoices();if(voices!=null&&!name.isEmpty())for(Voice v:voices)if(v.getName().equals(name)){speech.setVoice(v);break;}}
    private void stopAll(){cancelRequest();voice.close();if(speech!=null)speech.stop();setState("READY");answer("Stopped here. An AI request already sent may finish on the server.",false);}
    private void cancelRequest(){if(busy)lastReply="Request cancelled on this phone. It may still finish on the server.";generation++;if(request!=null)request.cancel();request=null;busy=false;}
    private void startRequest(String message){
        if(busy)return;if(!pairing.configured()){answer("My local commands are ready. For that question, connect your AI bridge in Settings first.",false);return;}
        final String endpoint=pairing.endpoint(),token;try{token=pairing.token();}catch(Exception e){answer("Please save the pairing details again in Settings.",false);return;}
        JSONObject payload=null;try{if(message!=null)payload=new JSONObject().put("message",message).put("history",conversations.history()).put("notes",new JSONArray(selectedNotes));}catch(JSONException e){answer("Could not prepare this question.",false);return;}
        final JSONObject body=payload;final int ticket=++generation;final BridgeClient client=new BridgeClient();request=client;busy=true;setState("THINKING");answer(message==null?"Checking your bridge…":"One moment, Andrew…",false);
        worker.execute(()->{String result;boolean success=false;try{JSONObject response=client.request(endpoint,token,body);if(message==null){if(!"jarvis-mobile-bridge".equals(response.optString("service"))||response.optInt("version")!=2)throw new IOException("Version mismatch");result="Bridge connected. Conversation and selected-note context are supported. Send a question to test the model.";}else{if(!response.has("actions_executed")||response.getBoolean("actions_executed"))throw new IOException();result=response.getString("reply");if(result.trim().isEmpty()||result.length()>16000)throw new IOException();}success=true;}catch(Exception e){result="I couldn't reach a compatible AI bridge. Check your connection and that bridge version 0.3 is running. Your notes are safe; nothing was executed.";}final String output=result;final boolean ok=success;runOnUiThread(()->{if(ticket!=generation||isFinishing()||isDestroyed())return;busy=false;request=null;setState(ok?"READY":"ERROR");if(ok&&message!=null){boolean stored=conversations.add(message,output,"ai");selectedNotes.clear();if(input!=null&&input.getText().toString().trim().equals(message)){input.setText("");draft="";}renderConversation();if(!stored)toast("Reply received, but conversation could not be saved.");}answer(output,ok&&message!=null);});});
    }
    private JSONArray notes(){try{return new JSONArray(prefs().getString("notes","[]"));}catch(JSONException e){return new JSONArray();}}
    private boolean saveNote(String raw){String note=raw.trim();if(note.isEmpty()||note.length()>4000)return false;JSONArray list=notes();if(list.length()>=200)return false;try{list.put(new JSONObject().put("text",note).put("at",System.currentTimeMillis()));return prefs().edit().putString("notes",list.toString()).commit();}catch(JSONException e){return false;}}
    private void saveDraft(){if(input==null)return;if(saveNote(input.getText().toString())){input.setText("");draft="";answer("Saved in Memory, on your phone.",true);}else answer("Enter a note first. Memory holds up to 200 notes, each up to 4,000 characters.",false);}
    private void chooseNotes(){JSONArray list=notes();if(list.length()==0){toast("Save a note first, then attach it to an AI question.");return;}String[] labels=new String[list.length()];boolean[] checked=new boolean[list.length()];for(int i=0;i<list.length();i++){String n=list.optJSONObject(i).optString("text");labels[i]=n.length()>100?n.substring(0,100)+"…":n;checked[i]=selectedNotes.contains(n);}new AlertDialog.Builder(this).setTitle("Notes for your next AI question").setMultiChoiceItems(labels,checked,(dialog,which,value)->checked[which]=value).setNegativeButton("Cancel",null).setPositiveButton("Attach",(dialog,which)->{ArrayList<String> selection=new ArrayList<>();int size=0;for(int i=0;i<checked.length;i++)if(checked[i]){String n=list.optJSONObject(i).optString("text");selection.add(n);size+=n.length();}if(size>4000||selection.size()>5){toast("Choose up to 5 notes, totalling at most 4,000 characters.");return;}selectedNotes.clear();selectedNotes.addAll(selection);lastReply=selection.size()+" notes selected. They will be sent to your AI bridge with the next question.";show("Jarvis");}).show();}
    private void memory(){heading("Memory","Your ideas and repair notes. Stored on this phone.");text(notes().length()+" / 200 NOTES",11,ACCENT);EditText search=edit("Search your notes…",false);row("Export notes",()->exportNotes(),"Add a note",()->{show("Jarvis");if(input!=null)input.requestFocus();});memoryList=new LinearLayout(this);memoryList.setOrientation(LinearLayout.VERTICAL);page.addView(memoryList);renderNotes("");search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){renderNotes(s.toString());}public void afterTextChanged(Editable e){}});text("Export files contain plain text. Keep them private. Uninstalling removes this app's notes.",12,MUTED);}
    private void renderNotes(String query){memoryList.removeAllViews();JSONArray list=notes();int found=0;for(int i=list.length()-1;i>=0;i--){JSONObject n=list.optJSONObject(i);if(n==null||!n.optString("text").toLowerCase(Locale.UK).contains(query.toLowerCase(Locale.UK)))continue;found++;final int index=i;LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(14),dp(12),dp(14),dp(12));card.setBackground(background(PANEL,EDGE,14));TextView t=label(n.optString("text"),17,TEXT);t.setTextIsSelectable(true);card.addView(t);card.addView(label(new java.text.SimpleDateFormat("d MMM yyyy • HH:mm",Locale.UK).format(new Date(n.optLong("at",0))),11,MUTED));card.addView(makeButton("Delete",false,()->new AlertDialog.Builder(this).setTitle("Delete this note?").setMessage(n.optString("text")).setNegativeButton("Keep",null).setPositiveButton("Delete",(d,w)->{JSONArray current=notes();current.remove(index);if(prefs().edit().putString("notes",current.toString()).commit()){selectedNotes.remove(n.optString("text"));renderNotes(query);}else toast("Could not delete note.");}).show()));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(6),0,dp(6));memoryList.addView(card,lp);}if(found==0)memoryList.addView(label("No matching notes yet.",16,MUTED));}
    private void exportNotes(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"Jarvis-notes.json");try{startActivityForResult(i,EXPORT);}catch(ActivityNotFoundException e){toast("No file picker available.");}}
    private void tasks(){heading("Task centre","Imported snapshots from your Jarvis ledger.");text("PC LINK: NOT CONNECTED",12,ACCENT);text("These are saved task states, not live updates. This app cannot approve or execute PC tasks.",15,MUTED);button("Import task snapshot",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(i,IMPORT);}catch(ActivityNotFoundException e){toast("No file picker available.");}});try{JSONObject snapshot=new JSONObject(prefs().getString("snapshot","{}"));text(snapshot.optBoolean("sample")?"SYNTHETIC DEMO":"OFFLINE SNAPSHOT",11,ACCENT);text("Exported: "+snapshot.optString("generated_at","Nothing imported yet"),12,MUTED);JSONArray rows=snapshot.optJSONArray("tasks");if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);text(row.getString("state").replace('_',' ')+"\n"+row.getString("id"),16,TEXT);}}catch(JSONException e){text("Please import the snapshot again.",16,TEXT);}}
    private void toggle(String title,String key,boolean fallback){Switch s=new Switch(this);s.setText(title);s.setTextColor(TEXT);s.setTextSize(15);s.setPadding(0,dp(12),0,dp(12));s.setChecked(prefs().getBoolean(key,fallback));s.setOnCheckedChangeListener((button,checked)->prefs().edit().putBoolean(key,checked).apply());page.addView(s);}
    private void settings(){heading("Control room","Voice, privacy and your AI connection.");text("VOICE",11,ACCENT);toggle("Speak replies aloud","speak_replies",true);toggle("Send when I finish speaking","voice_send",false);text("Automatic voice sending is optional. Microphone input stops when you leave the app.",12,MUTED);toggle("On-device speech only","local_speech",false);text(voice.localAvailable()?"On-device speech service detected. Language support still depends on your phone.":"On-device speech unavailable. System speech may process audio online.",12,MUTED);button("Choose a local English voice",()->chooseVoice());text("Speaking speed",13,MUTED);SeekBar speed=new SeekBar(this);speed.setMax(70);speed.setProgress(Math.round((prefs().getFloat("speech_rate",.95f)-.7f)*100));speed.setContentDescription("Speaking speed, 0.7 to 1.4 times normal");speed.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){applyVoice();}public void onProgressChanged(SeekBar b,int value,boolean user){if(user)prefs().edit().putFloat("speech_rate",.7f+value/100f).apply();}});page.addView(speed);button("Test voice",()->speak("At your service, Andrew. Jarvis is ready."));toggle("Reduce core animation","reduce_motion",false);
        text("AI BRIDGE",11,ACCENT);text("Use your private HTTPS bridge. Recent AI conversation and explicitly attached notes are included. PC control stays disabled.",14,MUTED);EditText address=edit("https://your-jarvis-address",false);address.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);address.setText(pairing.endpoint());EditText token=edit("Pairing token — not an AI API key",true);button("Save connection",()->{try{pairing.save(address.getText().toString(),token.getText().toString().trim());token.setText("");answer("Connection saved. Test it below.",false);}catch(Exception e){answer("Use an HTTPS origin and a valid 32–128 character pairing token.",false);}});row("Test bridge",()->startRequest(null),"Forget pairing",()->{cancelRequest();if(pairing.clear())answer("Pairing removed. Your notes and conversation are kept.",false);});reply=label(lastReply,15,TEXT);page.addView(reply);text("Jarvis Dev 0.3.0 • Wrekin Labs\nNo background listening, camera access or autonomous PC actions. Conversation keeps the latest 20 exchanges on this phone.",12,MUTED);
    }
    private void chooseVoice(){if(!speechReady){toast("Speech service is not ready yet.");return;}Set<Voice> all=speech.getVoices();ArrayList<Voice> choices=new ArrayList<>();if(all!=null)for(Voice v:all)if(v.getLocale().getLanguage().equals("en")&&!v.isNetworkConnectionRequired())choices.add(v);choices.sort(Comparator.comparing(Voice::getName));if(choices.isEmpty()){toast("No local English voice found. Install one in Android's text-to-speech settings.");return;}String[] names=new String[choices.size()];for(int i=0;i<names.length;i++)names[i]=choices.get(i).getLocale().getDisplayName()+" • "+choices.get(i).getName();new AlertDialog.Builder(this).setTitle("Choose voice").setItems(names,(d,index)->{prefs().edit().putString("voice",choices.get(index).getName()).apply();applyVoice();speak("At your service, Andrew.");}).show();}
    private void toast(String text){Toast.makeText(this,text,Toast.LENGTH_LONG).show();}
    private String validateSnapshot(String raw)throws JSONException{JSONObject source=new JSONObject(raw),clean=new JSONObject();if(source.getInt("schema_version")!=1)throw new JSONException("Version");JSONArray rows=source.getJSONArray("tasks"),safe=new JSONArray();if(rows.length()>500)throw new JSONException("Too large");Set<String> states=new HashSet<>(Arrays.asList("queued","awaiting_approval","running","completed","cancelled","unknown"));for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String id=row.getString("id"),state=row.getString("state");if(id.isEmpty()||id.length()>100||!states.contains(state))throw new JSONException("Task");safe.put(new JSONObject().put("id",id).put("state",state));}String stamp=source.getString("generated_at");if(stamp.length()>64)throw new JSONException("Date");return clean.put("schema_version",1).put("generated_at",stamp).put("sample",source.getBoolean("sample")).put("tasks",safe).toString();}
    @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;if(code==EXPORT){try(OutputStream out=getContentResolver().openOutputStream(data.getData(),"wt")){if(out==null)throw new IOException();out.write(new JSONObject().put("schema_version",1).put("notes",notes()).toString(2).getBytes(StandardCharsets.UTF_8));toast("Notes exported.");}catch(Exception e){toast("Could not export notes.");}}if(code==IMPORT){try(InputStream in=getContentResolver().openInputStream(data.getData());ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>262144)throw new IOException();out.write(b,0,n);}String clean=validateSnapshot(out.toString("UTF-8"));if(!prefs().edit().putString("snapshot",clean).commit())throw new IOException();show("Tasks");}catch(Exception e){toast("Invalid snapshot. Your previous import is unchanged.");}}}
    @Override protected void onSaveInstanceState(Bundle state){state.putString("screen",screen);state.putString("draft",input==null?draft:input.getText().toString());state.putString("reply",lastReply);state.putBoolean("busy",busy);state.putStringArrayList("attachments",selectedNotes);super.onSaveInstanceState(state);}
    @Override protected void onStart(){super.onStart();foreground=true;}
    @Override protected void onStop(){foreground=false;voice.close();if(speech!=null)speech.stop();if(!busy)setState("READY");super.onStop();}
    @Override protected void onDestroy(){cancelRequest();voice.close();worker.shutdownNow();if(speech!=null){speech.stop();speech.shutdown();}super.onDestroy();}
}
